function formatVoiceTime(seconds){if(!Number.isFinite(seconds)||seconds<0)return'--:--';const whole=Math.floor(seconds),minutes=Math.floor(whole/60),rest=String(whole%60).padStart(2,'0');return`${minutes}:${rest}`;}
