function updateVoiceProgress(id,audio){if(state.screen!=='voices'||state.audio!==audio)return;const duration=Number.isFinite(audio.duration)?audio.duration:voiceDurationCache.get(id)||0;if(duration>0)voiceDurationCache.set(id,duration);const current=Number.isFinite(audio.currentTime)?audio.currentTime:0,percent=duration>0?Math.min(100,current/duration*100):0,card=document.querySelector(`[data-voice-card="${id}"]`);if(!card)return;const bar=card.querySelector('.voice-seek'),elapsed=card.querySelector('.voice-elapsed'),total=card.querySelector('.voice-duration');if(bar){bar.style.setProperty('--voice-progress',`${percent}%`);bar.setAttribute('aria-valuenow',percent.toFixed(1));}if(elapsed)elapsed.textContent=formatVoiceTime(current);if(total)total.textContent=formatVoiceTime(duration);}
