function renderVoiceCard(p){const availability=state.voiceAvailable[p.id],interactive=availability!==false,loading=state.voiceLoading===p.id,playing=state.playing===p.id,audio=voiceAudioFor(p.id),paused=!!audio&&audio.paused&&!audio.ended&&!loading,failed=state.voiceLoadFailed.has(p.id),duration=audio&&Number.isFinite(audio.duration)?audio.duration:voiceDurationCache.get(p.id)||0,current=audio&&Number.isFinite(audio.currentTime)?audio.currentTime:0,progress=duration>0?Math.min(100,current/duration*100):0,status=availability===false?'NOT AVAILABLE':loading?'LOADING':playing?'NOW PLAYING':paused?'PAUSED':failed?'TRY AGAIN':state.heard.has(p.id)?'WITH LOVE ♡':'READY TO PLAY',playLabel=playing?'Ⅱ 暂停播放':paused?'▶ 继续播放':failed?'▶ 点击重试':state.heard.has(p.id)?'▶ 再听一次':'▶ 播放祝福';return `<article class="voice-card ${playing?'playing':''} ${paused?'paused':''} ${availability===false?'is-unavailable':''}" data-voice-card="${p.id}"${loading?' aria-busy="true"':''}>${voiceMoonScene(p.id)}<i class="voice-corner tl" aria-hidden="true"></i><i class="voice-corner tr" aria-hidden="true"></i><i class="voice-corner bl" aria-hidden="true"></i><i class="voice-corner br" aria-hidden="true"></i><div class="voice-record-wrap"><div class="voice-record">${avatar(p,'voice-portrait')}</div><span class="voice-spark" aria-hidden="true">✦</span></div><div class="voice-info"><span class="voice-status">${status}</span><strong class="voice-name">${esc(p.name)}</strong><div class="voice-wave" aria-hidden="true">${voiceWaveform(p.id)}</div><div class="voice-seek" role="progressbar" aria-label="${esc(p.name)}的播放进度" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${progress.toFixed(1)}" style="--voice-progress:${progress}%"><span></span></div><div class="voice-times"><span class="voice-elapsed">${formatVoiceTime(current)}</span><span class="voice-duration">${formatVoiceTime(duration)}</span></div><div class="voice-controls"><button class="voice-play-button" ${interactive?`data-voice-person="${p.id}"`:'disabled'}>${availability===false?'素材待补充':playLabel}</button><button class="voice-replay-button" aria-label="从头播放${esc(p.name)}的祝福" ${interactive?`data-voice-replay="${p.id}"`:'disabled'}>↺</button></div></div></article>`;}
function renderVoices(){const c=chapter(state.activeVoiceChapter),visited=voiceVisitedForChapter(c),activePerson=c.people.find(p=>p.id===state.activeVoice)||null,tabs=state.data.chapters.map(x=>`<button class="voice-tab ${x.id===c.id?'active':''}" data-voice-chapter="${x.id}">VOICE 0${x.id}</button>`).join(''),stars=c.people.map((p,index)=>renderVoiceStar(p,index,c.id,visited)).join(''),popup=activePerson?`<div class="voice-popup-shell" role="dialog" aria-modal="true" aria-label="${esc(activePerson.name)}的语音祝福"><button type="button" class="voice-popup-close" data-action="close-voice-popup" aria-label="关闭语音卡">×</button>${renderVoiceCard(activePerson)}</div>`:'';return shell(`<div class="voice-page"><header class="voice-header"><div class="voice-heading"><p class="voice-eyebrow">✦ BIRTHDAY RADIO</p><h2>把祝福，留在这一刻。</h2><p>最后一关，是一些想亲口对你说的话。</p></div><nav class="voice-chapter-tabs" aria-label="语音章节">${tabs}</nav></header><section class="voice-star-field" aria-label="语音祝福星空"><span class="voice-star-specks" aria-hidden="true"></span><span class="voice-constellation" aria-hidden="true"><i></i><i></i><i></i></span>${voiceStarCompanion()}${stars}<div class="voice-popup-layer${activePerson?' is-open':''}" aria-hidden="${!activePerson}">${popup}</div></section><p class="voice-footer-note">✦ MADE OF VOICES &amp; LITTLE WISHES</p><div class="voice-ending-actions"><button class="voice-ending-button" data-action="go-ending">继续查看结尾 Demo</button></div></div>`,{back:'go-select'});}
function stopAudio(){voiceLoadRun++;const audio=state.audio;if(audio){audio._voiceCleanup?.();audio.pause();audio.removeAttribute('src');try{audio.load();}catch(_){}}state.audio=null;state.playing=null;state.voiceLoading=null;}
function openVoicePopup(id){const c=chapter(state.activeVoiceChapter),person=c?.people.find(p=>p.id===id);if(!person)return;if(state.activeVoice&&state.activeVoice!==id)stopAudio();clearTimeout(voiceOpeningTimer);voiceVisitedForChapter(c).add(id);state.activeVoice=id;state.voiceOpening=id;render();requestAnimationFrame(()=>document.querySelector('.voice-popup-close')?.focus());voiceOpeningTimer=setTimeout(()=>{if(state.screen!=='voices'||state.activeVoice!==id||state.voiceOpening!==id)return;state.voiceOpening=null;render();},430);}
function closeVoicePopup(){const id=state.activeVoice;if(!id)return;clearTimeout(voiceOpeningTimer);stopAudio();state.activeVoice=null;state.voiceOpening=null;render();requestAnimationFrame(()=>document.querySelector(`[data-voice-star="${CSS.escape(String(id))}"]`)?.focus());}
function failVoiceAudio(audio,id){if(state.audio!==audio)return;audio._voiceCleanup?.();audio.pause();audio.removeAttribute('src');try{audio.load();}catch(_){}state.audio=null;state.playing=null;state.voiceLoading=null;state.voiceLoadFailed.add(id);render();}
function resumeVoiceAudio(audio,id,restart=false){if(state.audio!==audio)return;if(restart)audio.currentTime=0;state.voiceLoading=id;state.voiceLoadFailed.delete(id);render();let playback;try{playback=audio.play();}catch(_){return failVoiceAudio(audio,id);}if(playback?.catch)playback.catch(()=>failVoiceAudio(audio,id));}
function playVoice(id){if(state.voiceAvailable[id]===false||(state.voiceLoading===id&&state.playing!==id))return;const active=voiceAudioFor(id);if(active){if(!active.paused){active.pause();state.playing=null;state.voiceLoading=null;render();requestAnimationFrame(()=>updateVoiceProgress(id,active));return;}return resumeVoiceAudio(active,id,active.ended||active.currentTime>=active.duration-.05);}const preloaded=takeVoicePreload(id);cancelVoicePreloads();stopAudio();const token=voiceLoadRun,p=allPeople().find(x=>x.id===id);if(!p?.voice)return;const audio=preloaded||new Audio(),isActive=()=>token===voiceLoadRun&&state.screen==='voices'&&state.audio===audio,onMetadata=()=>{if(Number.isFinite(audio.duration)&&audio.duration>0)voiceDurationCache.set(id,audio.duration);updateVoiceProgress(id,audio);},onTime=()=>updateVoiceProgress(id,audio),onWaiting=()=>{if(!isActive()||audio.paused)return;state.voiceLoading=id;render();},onPlaying=()=>{if(!isActive())return;state.voiceAvailable[id]=true;state.voiceLoading=null;state.playing=id;state.voiceLoadFailed.delete(id);state.heard.add(id);if(Number.isFinite(audio.duration)&&audio.duration>0)voiceDurationCache.set(id,audio.duration);saveProgress();render();requestAnimationFrame(()=>updateVoiceProgress(id,audio));},onError=()=>{if(isActive())failVoiceAudio(audio,id);},onEnded=()=>{if(!isActive())return;state.playing=null;state.voiceLoading=null;updateVoiceProgress(id,audio);render();setTimeout(()=>{if(state.screen==='voices')preloadVoiceChapter(state.activeVoiceChapter);},0);},cleanup=()=>{audio.removeEventListener('error',onError);audio.removeEventListener('ended',onEnded);audio.removeEventListener('loadedmetadata',onMetadata);audio.removeEventListener('durationchange',onMetadata);audio.removeEventListener('timeupdate',onTime);audio.removeEventListener('waiting',onWaiting);audio.removeEventListener('playing',onPlaying);};audio._voiceCleanup=cleanup;audio._voiceId=id;audio.preload='auto';audio.addEventListener('error',onError);audio.addEventListener('ended',onEnded);audio.addEventListener('loadedmetadata',onMetadata);audio.addEventListener('durationchange',onMetadata);audio.addEventListener('timeupdate',onTime);audio.addEventListener('waiting',onWaiting);audio.addEventListener('playing',onPlaying);if(!preloaded)audio.src=encodeURI(p.voice);state.audio=audio;state.voiceLoading=id;state.voiceLoadFailed.delete(id);render();let playback;try{playback=audio.play();}catch(_){return failVoiceAudio(audio,id);}if(playback?.catch)playback.catch(()=>{if(isActive())failVoiceAudio(audio,id);});}
function replayVoice(id){if(state.voiceAvailable[id]===false||(state.voiceLoading===id&&state.playing!==id))return;const audio=voiceAudioFor(id);if(audio)return resumeVoiceAudio(audio,id,true);playVoice(id);}

function renderEnding(){const people=[...allPeople()].sort((a,b)=>Number(a.id)-Number(b.id)),nodes=people.map((p,i)=>{const x=i%6*20,y=Math.floor(i/6)*100/3;return `<div class="ending-avatar" data-person-id="${p.id}" aria-label="${esc(p.id)} ${esc(p.name)}"><i class="avatar-trail"></i><span class="avatar-shell ending-orb ending-sprite-face" style="--sprite-x:${x}%;--sprite-y:${y}%"></span></div>`;}).join('');return `<div class="ending-screen${state.pageEntering?' page-enter':''}" id="ending"><div class="ending-ambient"></div><figure class="ending-chibi" id="endingChibi"><img src="${ENDING_CENTER}" alt="小米坐在月亮上的Q版插画" loading="eager" decoding="async" fetchpriority="high"></figure><div class="ending-people">${nodes}</div><p class="ending-blessing">愿这些微小的光，安静地陪你走进新的一年。</p><div class="ending-controls"><button class="ending-link" data-action="go-voices">← 返回声音页</button><button class="ending-link" data-action="replay-ending">↻ Replay Animation</button></div></div>`;}
