function heartPoints(count,outerX,topY,bottomY,notchY){const bez=(p0,c1,c2,p1,t)=>{const m=1-t;return{x:m**3*p0.x+3*m*m*t*c1.x+3*m*t*t*c2.x+t**3*p1.x,y:m**3*p0.y+3*m*m*t*c1.y+3*m*t*t*c2.y+t**3*p1.y};},notch={x:0,y:-notchY},rightTop={x:outerX*.55,y:-topY},right={x:outerX,y:-topY*.1},tip={x:0,y:bottomY},left={x:-outerX,y:-topY*.1},leftTop={x:-outerX*.55,y:-topY},lowerX=Math.min(outerX*.92,Math.max(outerX*.72,notchY*1.04)),segments=[[notch,{x:outerX*.15,y:-notchY-topY*.12},{x:outerX*.36,y:-topY},rightTop],[rightTop,{x:outerX*.82,y:-topY},{x:outerX,y:-topY*.55},right],[right,{x:outerX,y:bottomY*.42},{x:lowerX,y:bottomY*.8},tip],[tip,{x:-lowerX,y:bottomY*.8},{x:-outerX,y:bottomY*.42},left],[left,{x:-outerX,y:-topY*.55},{x:-outerX*.82,y:-topY},leftTop],[leftTop,{x:-outerX*.36,y:-topY},{x:-outerX*.15,y:-notchY-topY*.12},notch]],s=[];let total=0;segments.forEach((segment,si)=>{for(let j=si?1:0;j<=400;j++){const p=bez(...segment,j/400);if(s.length){const q=s[s.length-1];total+=Math.hypot(p.x-q.x,p.y-q.y);}s.push({...p,d:total});}});return Array.from({length:count},(_,i)=>{const wanted=i/count*total;let lo=0,hi=s.length-1;while(lo<hi){const mid=(lo+hi)>>1;if(s[mid].d<wanted)lo=mid+1;else hi=mid;}return s[lo];});}
function seed(i,s=0){const x=Math.sin((i+1)*917.13+s*37.17)*43758.5453;return x-Math.floor(x);}
function layoutEnding(){const scene=document.querySelector('#ending'),nodes=[...document.querySelectorAll('.ending-avatar')];if(!scene||!nodes.length)return;const w=scene.clientWidth,h=scene.clientHeight,mobile=w<520,points=mobile?endingHeartMobile24:endingHeartDesktop24,size=mobile?20:30,boxW=mobile?w*.98:Math.min(w*.48,560),boxH=mobile?Math.min(h*.39,315):Math.min(h*.46,360),sg=Math.max(7,size*.42),per=Math.max(1,Math.floor((w-30+sg)/(size+sg))),rows=Math.ceil(nodes.length/per),bottom=h-Math.max(78,size*2.5),byId=new Map(points.map(p=>[p.id,p]));nodes.forEach((n,i)=>{const id=String(n.dataset.personId).padStart(2,'0'),p=byId.get(id)||points[i%points.length],tx=(p.x-50)/100*boxW,ty=(p.y-50)/100*boxH,row=Math.floor(i/per),start=row*per,num=Math.min(per,nodes.length-start),pos=i-start,rowW=num*size+(num-1)*sg,sx=(w-rowW)/2+size/2+pos*(size+sg)-w/2,sy=bottom-(rows-1-row)*(size+sg)-h*.43;n.style.setProperty('--ending-avatar-size',`${size}px`);Object.assign(n.dataset,{sx,sy,tx,ty});n.style.transform=`translate(${endingPhase==='gathered'?tx:sx}px,${endingPhase==='gathered'?ty:sy}px)`;});}
function startEndingAnimation(){clearEnding();const scene=document.querySelector('#ending'),chibi=document.querySelector('#endingChibi'),nodes=[...document.querySelectorAll('.ending-avatar')];if(!scene||!chibi)return;endingPhase='idle';layoutEnding();const token=endingRun,reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,start=420,stagger=95,travel=1850;scene.classList.remove('chibi-visible','gathered','heart-pulse');nodes.forEach(n=>n.classList.remove('moving','arrived'));startEndingAudio();if(reduced){const reducedStart=260,reducedStagger=85,durations=nodes.map((_,i)=>950+seed(i,12)*180),reveal=Math.max(...durations.map((d,i)=>i*reducedStagger+d));endingPhase='moving';chibi.style.setProperty('--ending-reveal',`${reveal}ms`);endingTimers.push(setTimeout(()=>{if(token===endingRun)scene.classList.add('chibi-visible');},reducedStart));nodes.forEach((node,i)=>{const sx=+node.dataset.sx,sy=+node.dataset.sy,tx=+node.dataset.tx,ty=+node.dataset.ty;endingTimers.push(setTimeout(()=>{if(token!==endingRun)return;node.classList.add('moving');const a=node.animate([{transform:`translate(${sx}px,${sy}px)`},{transform:`translate(${tx}px,${ty}px)`}],{duration:durations[i],easing:'cubic-bezier(.22,.46,.36,1)',fill:'forwards'});a.finished.then(()=>{if(token===endingRun){node.style.transform=`translate(${tx}px,${ty}px)`;node.classList.remove('moving');node.classList.add('arrived');}}).catch(()=>{});},reducedStart+i*reducedStagger));});endingTimers.push(setTimeout(()=>{if(token!==endingRun)return;endingPhase='gathered';scene.classList.add('gathered');endingTimers.push(setTimeout(()=>{if(token===endingRun&&state.screen==='ending')window.EndingFireworks?.start(scene);},120));},reducedStart+reveal+100));return;}endingPhase='moving';const durations=nodes.map((_,i)=>travel+seed(i,12)*260),reveal=Math.max(...durations.map((d,i)=>i*stagger+d));chibi.style.setProperty('--ending-reveal',`${reveal}ms`);endingTimers.push(setTimeout(()=>{if(token===endingRun)scene.classList.add('chibi-visible');},start));nodes.forEach((node,i)=>{const sx=+node.dataset.sx,sy=+node.dataset.sy,tx=+node.dataset.tx,ty=+node.dataset.ty,dx=tx-sx,dy=ty-sy,len=Math.max(Math.hypot(dx,dy),1),bend=(i%2?1:-1)*Math.min(38,len*.075),cx=sx+dx*.52-dy/len*bend,cy=sy+dy*.52+dx/len*bend;endingTimers.push(setTimeout(()=>{if(token!==endingRun)return;node.classList.add('moving');const a=node.animate([{transform:`translate(${sx}px,${sy}px)`},{transform:`translate(${cx}px,${cy}px)`,offset:.52},{transform:`translate(${tx}px,${ty}px)`}],{duration:durations[i],easing:'cubic-bezier(.3,.03,.18,1)',fill:'forwards'});a.finished.then(()=>{if(token===endingRun){node.style.transform=`translate(${tx}px,${ty}px)`;node.classList.remove('moving');node.classList.add('arrived');}}).catch(()=>{});},start+i*stagger));});endingTimers.push(setTimeout(()=>{if(token!==endingRun)return;endingPhase='gathered';scene.classList.add('gathered','heart-pulse');endingTimers.push(setTimeout(()=>{if(token===endingRun)scene.classList.remove('heart-pulse');},1200));endingTimers.push(setTimeout(()=>{if(token===endingRun&&state.screen==='ending')window.EndingFireworks?.start(scene);},120));},start+reveal+120));}
async function replayEndingAnimation(){const replayToken=++endingReplayRun;clearEnding();const scene=document.querySelector('#ending'),chibi=document.querySelector('#endingChibi'),nodes=[...document.querySelectorAll('.ending-avatar')];if(!scene||!chibi||state.screen!=='ending')return;scene.dataset.replayToken=String(replayToken);const ownsReset=()=>replayToken===endingReplayRun&&scene.dataset.replayToken===String(replayToken)&&state.screen==='ending';scene.classList.add('ending-resetting');scene.classList.remove('chibi-visible','gathered','heart-pulse');nodes.forEach(n=>{n.getAnimations().forEach(a=>a.cancel());n.classList.remove('moving','arrived');});chibi.getAnimations().forEach(a=>a.cancel());endingPhase='idle';layoutEnding();nodes.forEach(n=>{const sx=+n.dataset.sx,sy=+n.dataset.sy;n.style.transform='translate('+sx+'px,'+sy+'px)';});chibi.style.opacity='0';chibi.style.transform='scale(.62)';void scene.offsetWidth;await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));if(!ownsReset())return;if(scene.clientWidth>=520){await wait(100);if(!ownsReset())return;}scene.classList.remove('ending-resetting');chibi.style.removeProperty('opacity');chibi.style.removeProperty('transform');void scene.offsetWidth;await new Promise(resolve=>requestAnimationFrame(resolve));if(!ownsReset())return;delete scene.dataset.replayToken;startEndingAnimation();}

app.addEventListener('click',e=>{const star=e.target.closest('[data-voice-star]');if(star){openVoicePopup(star.dataset.voiceStar);return;}if(e.target.closest('.voice-popup-close')||e.target.classList.contains('voice-popup-layer')){closeVoicePopup();return;}const tab=e.target.closest('[data-voice-chapter]');if(tab&&Number(tab.dataset.voiceChapter)!==state.activeVoiceChapter){clearTimeout(voiceOpeningTimer);state.activeVoice=null;state.voiceOpening=null;}if(e.target.closest('[data-action="go-voices"]')){clearTimeout(voiceOpeningTimer);state.activeVoice=null;state.voiceOpening=null;}});
app.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.c2Key&&ch02SuppressClick){ch02SuppressClick=false;return;}const a=el.dataset.action;if(a==='begin-story'){const intro=document.querySelector('#intro');if(intro?.classList.contains('leaving'))return;startBgm();preloadImageSet(['assets/pixel-ui/chapter-covers-sprite.webp']);intro?.classList.add('leaving');el.disabled=true;transitionTimer=setTimeout(()=>navigate('select'),1500);return;}if(a==='go-start')navigate('start');if(a==='go-select')navigate('select');if(a==='go-voices'&&voiceUnlocked())navigate('voices');if(a==='go-ending')enterEnding();if(a==='replay-ending')replayEndingAnimation();if(a==='reset-progress')resetProgress();if(el.dataset.chapter)beginChapter(Number(el.dataset.chapter));if(el.dataset.c1Person){clearFeedback();state.game.selectedPerson=el.dataset.c1Person;tryC1();}if(el.dataset.c1Sentence){clearFeedback();state.game.selectedSentence=el.dataset.c1Sentence;tryC1();}if(el.dataset.c2Key){clearFeedback();state.game.selectedKeyword=el.dataset.c2Key;setFeedback('已选择词条，请点击人物。');render();}if(el.dataset.c2Person){clearFeedback();placeKeyword(el.dataset.c2Person);}if(a==='submit-answer'){clearFeedback();submitAnswer();}if(a==='show-hint'){clearFeedback();state.game.hint=true;render();}if(a==='reveal-answer'){clearFeedback();state.game.reveal=true;render();}if(a==='accept-reveal'){clearFeedback();nextRiddle();}if(el.dataset.c4Person){clearFeedback();selectC4Person(el.dataset.c4Person);}if(el.dataset.c4Image){clearFeedback();matchC4Image(el.dataset.c4Image);}if(el.dataset.message){const id=state.game.chapterId;state.viewed[id]||=[];if(!state.viewed[id].includes(el.dataset.message))state.viewed[id].push(el.dataset.message);state.game.activeMessage=el.dataset.message;saveProgress();render();}if(el.dataset.voiceChapter){stopAudio();state.activeVoiceChapter=Number(el.dataset.voiceChapter);render();checkVoicesForChapter(state.activeVoiceChapter);preloadVoiceChapter(state.activeVoiceChapter);}if(el.dataset.voicePerson)playVoice(el.dataset.voicePerson);if(el.dataset.voiceReplay)replayVoice(el.dataset.voiceReplay);});
app.addEventListener('pointerdown',startCh02Drag);
app.addEventListener('pointermove',moveCh02Drag);
app.addEventListener('pointerup',event=>endCh02Drag(event));
app.addEventListener('pointercancel',event=>endCh02Drag(event,true));
app.addEventListener('error',e=>{const image=e.target;if(!(image instanceof HTMLImageElement))return;console.warn('Asset failed to load:',image.src);if(image.classList.contains('avatar-img'))image.closest('.avatar-shell')?.classList.add('image-error');if(image.classList.contains('clue-img'))image.parentElement?.classList.add('image-error');},{capture:true});
app.addEventListener('load',e=>{const image=e.target;if(image instanceof HTMLImageElement&&image.classList.contains('riddle-image'))markRiddleImageReady(image);},{capture:true});
app.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.screen==='voices'&&state.activeVoice){closeVoicePopup();return;}if(e.key==='Enter'&&state.screen==='game'&&state.game.chapterId===3&&document.activeElement.id==='answer'){clearFeedback();submitAnswer();}});
let resizeTimer;addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(state.screen==='ending')layoutEnding();},180);});
async function init(){try{const r=await fetch('people_data.json');if(!r.ok)throw new Error('无法读取人物数据');state.data=await r.json();if(!Array.isArray(state.data.chapters)||state.data.chapters.length!==4)throw new Error('人物数据格式不正确');loadProgress();render();}catch(error){app.innerHTML=`<div class="error"><div><h2>试玩版无法启动</h2><p>${esc(error.message)}</p><p>请通过本地服务器或 GitHub Pages 打开。</p></div></div>`;}}
app.innerHTML='<div class="loading">正在准备生日线索…</div>';init();
